using System.Globalization;
using Microsoft.AspNetCore.Http.HttpResults;
using Microsoft.EntityFrameworkCore;
using RelayPulse.Api.Data;
using RelayPulse.Core.Pulse;
using RelayPulse.Core.Statistics;

namespace RelayPulse.Api.Pulse;

public static class PulseEndpoints
{
    public const string InvalidWeek = "pulse.invalid_week";
    public const string AccountNotFound = "pulse.account_not_found";

    public static IEndpointRouteBuilder MapPulse(this IEndpointRouteBuilder app)
    {
        app.MapGet("/api/accounts/{id:int}/pulse", GetPulseAsync);
        return app;
    }

    private static async Task<Results<Ok<PulseResponse>, ProblemHttpResult>> GetPulseAsync(
        int id,
        string? week,
        RelayDbContext db,
        PulseQuery query,
        ILoggerFactory loggerFactory,
        CancellationToken cancellationToken)
    {
        var logger = loggerFactory.CreateLogger(typeof(PulseEndpoints).FullName!);
        DateOnly? requested = null;
        if (week is not null)
        {
            if (!DateOnly.TryParseExact(week, "yyyy-MM-dd", CultureInfo.InvariantCulture, DateTimeStyles.None, out var parsed))
            {
                return Problem(400, InvalidWeek, $"'{week}' is not a date in YYYY-MM-DD form.");
            }

            requested = parsed;
        }

        var account = await db.Accounts.AsNoTracking().SingleOrDefaultAsync(a => a.Id == id, cancellationToken);
        if (account is null)
        {
            return Problem(404, AccountNotFound, $"No account with id {id}.");
        }

        // Complete weeks come from week_buckets, which is built from the global MIN/MAX(occurred_at):
        // the default is the last complete week of the data, never of the wall clock.
        var completeWeeks = await db.WeekBuckets.AsNoTracking()
            .Where(b => b.Timezone == account.Timezone && b.IsComplete)
            .OrderBy(b => b.WeekStartLocal)
            .Select(b => b.WeekStartLocal)
            .ToListAsync(cancellationToken);

        if (completeWeeks.Count == 0)
        {
            // No data loaded at all: only an explicit week is a bad parameter.
            if (requested is not null)
            {
                return Problem(400, InvalidWeek, "There are no complete weeks of data yet.");
            }

            var nothing = new PulseRow(null, 0, Verdict.InsufficientHistory, null, null, null, null, 0, []);
            return TypedResults.Ok(new PulseResponse(account.Id, account.Name, account.Timezone, null, "empty", nothing, []));
        }

        var target = requested ?? completeWeeks[^1];
        var index = completeWeeks.BinarySearch(target);
        if (index < 0)
        {
            return Problem(400, InvalidWeek,
                $"{target:yyyy-MM-dd} is not the Monday of a complete week; choose a Monday from " +
                $"{completeWeeks[0]:yyyy-MM-dd} to {completeWeeks[^1]:yyyy-MM-dd}.");
        }

        // All complete weeks up to the target, not just the baseline window: the location list and
        // "has any events" are properties of the whole history (PulseBuilder.Build's contract).
        var rows = await query.RunAsync(id, completeWeeks[0], target, cancellationToken);
        var report = PulseBuilder.Build(completeWeeks, target, rows);

        logger.LogInformation("Pulse: served {AccountId} week {Week}", id, target.ToString("yyyy-MM-dd", CultureInfo.InvariantCulture));

        return TypedResults.Ok(new PulseResponse(
            account.Id,
            account.Name,
            account.Timezone,
            new PulsePeriod(
                target,
                target.AddDays(6),
                requested is null,
                completeWeeks[0],
                completeWeeks[^1],
                index > 0 ? completeWeeks[index - 1] : null,
                index < completeWeeks.Count - 1 ? completeWeeks[index + 1] : null),
            report.HasEvents ? "ok" : "empty",
            PulseRow.From(report.Account),
            report.Locations.Select(PulseRow.From).ToList()));
    }

    private static ProblemHttpResult Problem(int status, string code, string detail) =>
        TypedResults.Problem(statusCode: status, title: code, detail: detail);
}
using System.Data;
using Microsoft.Data.SqlClient;
using Microsoft.EntityFrameworkCore;
using RelayPulse.Api.Data;
using RelayPulse.Core.Pulse;

namespace RelayPulse.Api.Pulse;

/// <summary>The aggregation: weekly counts for one account at both grains, in one statement.</summary>
public sealed class PulseQuery(RelayDbContext db)
{
    // Events are bucketed by a range join onto the account timezone's precomputed weeks, so
    // bucketing is account-local and DST-correct, and partial weeks are excluded by a column
    // rather than by date arithmetic. Reads the dedupe view, never the raw table.
    //
    // GROUPING SETS: the first set is the location grain, the second the account grain (its
    // location comes back NULL, which the NOT NULL column can never produce by itself).
    private const string Sql = $"""
        SELECT b.week_start_local AS WeekStart,
               e.location         AS Location,
               e.event_type       AS EventType,
               e.outcome          AS Outcome,
               COUNT(*)           AS Events
        FROM accounts a
        JOIN week_buckets b
          ON b.timezone = a.timezone
         AND b.is_complete = 1 -- backstop only: PulseEndpoints' complete-week list owns the rule (T3 mutation b′)
         AND b.week_start_local >= @from
         AND b.week_start_local <= @to
        JOIN {RelayDbContext.DedupView} e
          ON e.account_id = a.id
         AND e.occurred_at >= b.utc_start
         AND e.occurred_at <  b.utc_end
        WHERE a.id = @accountId
        GROUP BY GROUPING SETS (
            (b.week_start_local, e.location, e.event_type, e.outcome),
            (b.week_start_local, e.event_type, e.outcome)
        )
        """;

    public Task<List<WeeklyCount>> RunAsync(int accountId, DateOnly from, DateOnly to, CancellationToken cancellationToken) =>
        db.Database
            .SqlQueryRaw<WeeklyCount>(
                Sql,
                new SqlParameter("@accountId", SqlDbType.Int) { Value = accountId },
                new SqlParameter("@from", SqlDbType.Date) { Value = from },
                new SqlParameter("@to", SqlDbType.Date) { Value = to })
            .ToListAsync(cancellationToken);
}
using Microsoft.EntityFrameworkCore;
using RelayPulse.Api.Data;

namespace RelayPulse.Api.Accounts;

/// <summary>Account picker entry. No auth yet (PLAN.md §7): every account is listed.</summary>
public sealed record AccountSummary(int Id, string Name, string Timezone);

public static class AccountEndpoints
{
    public static IEndpointRouteBuilder MapAccounts(this IEndpointRouteBuilder app)
    {
        app.MapGet("/api/accounts", GetAccountsAsync);
        return app;
    }

    private static async Task<List<AccountSummary>> GetAccountsAsync(RelayDbContext db, CancellationToken cancellationToken) =>
        await db.Accounts.AsNoTracking()
            .OrderBy(a => a.Id)
            .Select(a => new AccountSummary(a.Id, a.Name, a.Timezone))
            .ToListAsync(cancellationToken);
}
using Microsoft.EntityFrameworkCore;
using RelayPulse.Core.Time;

namespace RelayPulse.Api.Data;

public sealed class RelayDbContext(DbContextOptions<RelayDbContext> options) : DbContext(options)
{
    /// <summary>Exact-duplicate-free projection of activity_events. All reporting reads use it.</summary>
    public const string DedupView = "activity_events_dedup";

    public DbSet<Account> Accounts => Set<Account>();
    public DbSet<ActivityEvent> ActivityEvents => Set<ActivityEvent>();
    public DbSet<WeekBucket> WeekBuckets => Set<WeekBucket>();

    protected override void ConfigureConventions(ModelConfigurationBuilder configurationBuilder)
    {
        configurationBuilder.Properties<DateTime>()
            .HaveConversion<UtcDateTimeConverter>()
            .HaveColumnType("datetime2");

        // Properties<> covers mapped entities only. Raw SQL (SqlQueryRaw<T> into unmapped types,
        // i.e. the aggregation) uses the default type mapping, which otherwise yields Unspecified.
        configurationBuilder.DefaultTypeMapping<DateTime>()
            .HasConversion<UtcDateTimeConverter>();
    }

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // Mirrors db/schema.sql: snake_case names, explicit ids (no IDENTITY), varchar widths.
        modelBuilder.Entity<Account>(e =>
        {
            e.ToTable("accounts");
            e.HasKey(a => a.Id);
            e.Property(a => a.Id).HasColumnName("id").ValueGeneratedNever();
            e.Property(a => a.Name).HasColumnName("name").HasMaxLength(120).IsUnicode(false);
            e.Property(a => a.Industry).HasColumnName("industry").HasMaxLength(60).IsUnicode(false);
            e.Property(a => a.Timezone).HasColumnName("timezone").HasMaxLength(60).IsUnicode(false);
            e.Property(a => a.CreatedAt).HasColumnName("created_at");
        });

        modelBuilder.Entity<ActivityEvent>(e =>
        {
            e.ToTable("activity_events");
            e.HasKey(x => x.Id);
            e.Property(x => x.Id).HasColumnName("id").ValueGeneratedNever();
            e.Property(x => x.AccountId).HasColumnName("account_id");
            e.Property(x => x.Location).HasColumnName("location").HasMaxLength(80).IsUnicode(false);
            e.Property(x => x.EventType).HasColumnName("event_type").HasMaxLength(40).IsUnicode(false);
            e.Property(x => x.OccurredAt).HasColumnName("occurred_at");
            e.Property(x => x.DurationSeconds).HasColumnName("duration_seconds");
            e.Property(x => x.Outcome).HasColumnName("outcome").HasMaxLength(40).IsUnicode(false);

            e.HasOne<Account>().WithMany().HasForeignKey(x => x.AccountId).OnDelete(DeleteBehavior.Restrict);
            e.HasIndex(x => new { x.AccountId, x.OccurredAt }).HasDatabaseName("ix_activity_events_account_occurred");
        });

        modelBuilder.Entity<WeekBucket>(e =>
        {
            e.ToTable("week_buckets");
            e.HasKey(b => new { b.Timezone, b.WeekStartLocal });
            e.Property(b => b.Timezone).HasColumnName("timezone").HasMaxLength(60).IsUnicode(false);
            e.Property(b => b.WeekStartLocal).HasColumnName("week_start_local");
            e.Property(b => b.UtcStart).HasColumnName("utc_start");
            e.Property(b => b.UtcEnd).HasColumnName("utc_end");
            e.Property(b => b.IsComplete).HasColumnName("is_complete");

            // The aggregation range-joins on (timezone, utc_start <= occurred_at < utc_end).
            e.HasIndex(b => new { b.Timezone, b.UtcStart })
                .IsUnique()
                .IncludeProperties(b => new { b.UtcEnd, b.WeekStartLocal, b.IsComplete })
                .HasDatabaseName("ix_week_buckets_timezone_utc_start");
        });
    }
}
namespace RelayPulse.Api.Data;

public sealed class Account
{
    public int Id { get; set; }
    public required string Name { get; set; }
    public required string Industry { get; set; }

    /// <summary>IANA id. One per account; the schema cannot express per-location zones.</summary>
    public required string Timezone { get; set; }

    /// <summary>UTC. Not the start of history — never window on it.</summary>
    public DateTime CreatedAt { get; set; }
}
namespace RelayPulse.Api.Data;

/// <summary>Raw table row. Reporting reads go through the activity_events_dedup view, not this.</summary>
public sealed class ActivityEvent
{
    public int Id { get; set; }
    public int AccountId { get; set; }
    public required string Location { get; set; }
    public required string EventType { get; set; }

    /// <summary>UTC.</summary>
    public DateTime OccurredAt { get; set; }

    public int? DurationSeconds { get; set; }
    public string? Outcome { get; set; }
}
namespace RelayPulse.Core.Time;

/// <summary>
/// One Mon–Sun week in a timezone's local calendar, expressed as a half-open UTC range
/// [<see cref="UtcStart"/>, <see cref="UtcEnd"/>) so events can be bucketed with a range join.
/// </summary>
/// <param name="IsComplete">
/// True only when all 7 local days fall inside the observation window. A property of the window,
/// not of where events land: a complete week can hold zero events.
/// </param>
public sealed record WeekBucket(
    string Timezone,
    DateOnly WeekStartLocal,
    DateTime UtcStart,
    DateTime UtcEnd,
    bool IsComplete);

