namespace RelayPulse.Core.Statistics;

/// <param name="RankKey">
/// min(p_low/α_low, p_high/α_high). Below 1 exactly when flagged, so ascending order puts every
/// flagged row first, most extreme at the top. +∞ when no verdict was reached.
/// </param>
/// <param name="Lambda">Expected count; null when history is insufficient.</param>
/// <param name="Band">Counts that would be Normal at this λ; null unless the row was actually judged.</param>
/// <param name="PLow">P(X ≤ count); null when λ is null.</param>
/// <param name="PHigh">P(X ≥ count); null when λ is null.</param>
public sealed record Assessment(
    Verdict Verdict,
    double RankKey,
    double? Lambda = null,
    CountBand? Band = null,
    double? PLow = null,
    double? PHigh = null);
namespace RelayPulse.Core.Statistics;

/// <summary>
/// Expected weekly rate λ from a series' own history: the trailing <see cref="Window"/> complete
/// weeks, one highest and one lowest dropped, mean of the rest. The trim is what keeps a single
/// anomaly week (acct 6, 2026-06-01) from inflating the baselines that follow it.
/// </summary>
public static class Baseline
{
    public const int Window = 12;
    public const int MinWeeks = 8;

    /// <param name="priorCompleteWeeks">
    /// Counts for complete weeks strictly before the week being judged, oldest first. The caller
    /// excludes partial weeks; only the last <see cref="Window"/> are used.
    /// </param>
    /// <returns>λ, or <c>null</c> when fewer than <see cref="MinWeeks"/> weeks are available.</returns>
    public static double? Lambda(IReadOnlyList<int> priorCompleteWeeks)
    {
        ArgumentNullException.ThrowIfNull(priorCompleteWeeks);
        if (priorCompleteWeeks.Any(c => c < 0))
        {
            throw new ArgumentOutOfRangeException(nameof(priorCompleteWeeks), "Weekly counts cannot be negative.");
        }

        if (priorCompleteWeeks.Count < MinWeeks)
        {
            return null;
        }

        var sorted = priorCompleteWeeks
            .Skip(Math.Max(0, priorCompleteWeeks.Count - Window))
            .Order()
            .ToArray();

        return sorted[1..^1].Average();
    }
}
namespace RelayPulse.Core.Statistics;

/// <summary>Inclusive range of weekly counts that would be judged normal for a given λ.</summary>
public sealed record CountBand(int Lo, int Hi);
namespace RelayPulse.Core.Statistics;

/// <summary>
/// Exact Poisson tail probabilities. Terms are built by the recurrence
/// ln p(k) = ln p(k−1) + ln λ − ln k and summed relative to the largest term, so there are no
/// factorials and nothing overflows or underflows prematurely (λ = 500 and beyond).
/// </summary>
public static class PoissonTail
{
    // Stop summing the upper tail once a term adds less than this, relative to the sum so far.
    private const double Epsilon = 1e-17;

    /// <summary>P(X ≤ n).</summary>
    public static double Lower(int n, double lambda)
    {
        EnsureValid(lambda);
        if (n < 0)
        {
            return 0.0;
        }

        if (lambda == 0.0)
        {
            return 1.0;
        }

        // Every term is positive, so a direct sum is stable; scale by the largest (the mode, or
        // the last term when n sits below the mode) to keep exp() in range.
        var logLambda = Math.Log(lambda);
        var peak = LogPmf(Math.Min(n, (int)Math.Floor(lambda)), lambda, logLambda);
        var logTerm = -lambda;
        var sum = 0.0;
        for (var k = 0; k <= n; k++)
        {
            if (k > 0)
            {
                logTerm += logLambda - Math.Log(k);
            }

            sum += Math.Exp(logTerm - peak);
        }

        return Math.Min(1.0, Math.Exp(peak) * sum);
    }

    /// <summary>P(X ≥ n) = 1 − P(X ≤ n−1).</summary>
    public static double Upper(int n, double lambda)
    {
        EnsureValid(lambda);
        if (n <= 0)
        {
            return 1.0;
        }

        if (lambda == 0.0)
        {
            return 0.0;
        }

        // At or below the mean the upper tail is large and the complement loses nothing.
        if (n <= lambda)
        {
            return 1.0 - Lower(n - 1, lambda);
        }

        // Past the mean, 1 − P(X ≤ n−1) cancels catastrophically; sum the tail directly. Terms
        // shrink monotonically for k > λ, so stop once they stop mattering.
        var first = LogPmf(n, lambda, Math.Log(lambda));
        var term = 1.0;
        var sum = 0.0;
        for (var k = n; term > Epsilon * sum; k++)
        {
            sum += term;
            term *= lambda / (k + 1);
        }

        return Math.Exp(first) * sum;
    }

    private static double LogPmf(int k, double lambda, double logLambda)
    {
        var log = -lambda;
        for (var j = 1; j <= k; j++)
        {
            log += logLambda - Math.Log(j);
        }

        return log;
    }

    private static void EnsureValid(double lambda)
    {
        if (!double.IsFinite(lambda) || lambda < 0.0)
        {
            throw new ArgumentOutOfRangeException(nameof(lambda), lambda, "λ must be finite and non-negative.");
        }
    }
}
namespace RelayPulse.Core.Statistics;

/// <summary>
/// Exact Poisson tail tests against the baseline λ. Asymmetric on purpose: the low tail
/// (α = 0.025) is 5× more sensitive than the high tail (α = 0.005).
/// </summary>
public static class Significance
{
    public const double AlphaLow = 0.025;
    public const double AlphaHigh = 0.005;

    /// <summary>
    /// Volume gate. Just above ln(1/α_low) = 3.689, the λ at which an empty week first becomes
    /// detectable as Below.
    /// </summary>
    public const double MinLambda = 3.7;

    /// <summary>The integer counts <see cref="Assess"/> would call Normal, ignoring the volume gate.</summary>
    public static CountBand BandFor(double lambda)
    {
        // Lower(n) rises with n and Upper(n) falls, so both edges are binary searches.
        // lo: smallest n with P(X ≤ n) ≥ α_low. P(X ≤ ⌈λ⌉) ≥ ~½, so it is never above ⌈λ⌉.
        var lo = FirstWhere(0, (int)Math.Ceiling(lambda), n => PoissonTail.Lower(n, lambda) >= AlphaLow);

        // hi: one below the smallest n with P(X ≥ n) < α_high. λ + 10√λ + 20 is far past it.
        var ceiling = (int)Math.Ceiling(lambda + 10 * Math.Sqrt(lambda) + 20);
        var hi = FirstWhere(1, ceiling, n => PoissonTail.Upper(n, lambda) < AlphaHigh) - 1;

        return new CountBand(lo, hi);
    }

    public static Assessment Assess(int count, double? lambda)
    {
        ArgumentOutOfRangeException.ThrowIfNegative(count);
        if (lambda is not { } l)
        {
            return new Assessment(Verdict.InsufficientHistory, double.PositiveInfinity);
        }

        var pLow = PoissonTail.Lower(count, l);
        var pHigh = PoissonTail.Upper(count, l);

        if (l < MinLambda)
        {
            // No band: a gated row is never flagged, so "counts outside this range get flagged" would be false.
            return new Assessment(Verdict.NotEnoughVolume, double.PositiveInfinity, l, null, pLow, pHigh);
        }

        var band = BandFor(l);

        var verdict = pLow < AlphaLow ? Verdict.Below
            : pHigh < AlphaHigh ? Verdict.Above
            : Verdict.Normal;

        return new Assessment(verdict, Math.Min(pLow / AlphaLow, pHigh / AlphaHigh), l, band, pLow, pHigh);
    }

    // Smallest n in [from, to] for a monotone predicate (false…false, true…true); `to` if none holds.
    private static int FirstWhere(int from, int to, Func<int, bool> predicate)
    {
        while (from < to)
        {
            var mid = from + (to - from) / 2;
            if (predicate(mid))
            {
                to = mid;
            }
            else
            {
                from = mid + 1;
            }
        }

        return from;
    }
}
namespace RelayPulse.Core.Statistics;

public enum Verdict
{
    Normal,
    Above,
    Below,

    /// <summary>λ below <see cref="Significance.MinLambda"/>: only large swings would be detectable.</summary>
    NotEnoughVolume,

    /// <summary>Fewer than <see cref="Baseline.MinWeeks"/> prior complete weeks.</summary>
    InsufficientHistory,
}
using RelayPulse.Core.Statistics;

namespace RelayPulse.Core.Pulse;

/// <summary>
/// Turns aggregation rows into judged series for one account-week. Pure: no clock, no I/O.
/// </summary>
public static class PulseBuilder
{
    public const string UnspecifiedOutcome = "unspecified";

    /// <param name="completeWeeks">
    /// The account timezone's complete week Mondays, ascending. These define the zero-fill: every
    /// series gets a count for each of them, and nothing outside them is ever read.
    /// </param>
    /// <param name="week">The week being judged; must be one of <paramref name="completeWeeks"/>.</param>
    /// <param name="rows">
    /// Both grains from the aggregation query, covering every complete week up to
    /// <paramref name="week"/>: a week with no rows is read as zero events, and the location list
    /// and <see cref="PulseReport.HasEvents"/> come from these rows. Rows outside the window are ignored.
    /// </param>
    public static PulseReport Build(IReadOnlyList<DateOnly> completeWeeks, DateOnly week, IReadOnlyList<WeeklyCount> rows)
    {
        ArgumentNullException.ThrowIfNull(completeWeeks);
        ArgumentNullException.ThrowIfNull(rows);

        var targetIndex = IndexOf(completeWeeks, week);
        if (targetIndex < 0)
        {
            throw new ArgumentException($"{week:yyyy-MM-dd} is not a complete week.", nameof(week));
        }

        // Up to and including the target; weeks after it and partial weeks never enter.
        var inWindow = completeWeeks.Take(targetIndex + 1).ToHashSet();
        var relevant = rows.Where(r => inWindow.Contains(r.WeekStart)).ToList();
        var prior = completeWeeks.Take(targetIndex).ToList();

        if (relevant.Count == 0)
        {
            // No events at all is no history, not a zero-volume history.
            var empty = new SeriesPulse(null, 0, Math.Min(prior.Count, Baseline.Window), Significance.Assess(0, null), []);
            return new PulseReport(false, empty, []);
        }

        var account = Judge(null, relevant.Where(r => r.Location is null).ToList(), prior, week);
        var locations = relevant
            .Where(r => r.Location is not null)
            .GroupBy(r => r.Location!, StringComparer.Ordinal)
            .Select(g => Judge(g.Key, g.ToList(), prior, week))
            .OrderBy(s => s.Assessment.RankKey)
            .ThenBy(s => s.Location, StringComparer.Ordinal)
            .ToList();

        return new PulseReport(true, account, locations);
    }

    private static SeriesPulse Judge(string? location, List<WeeklyCount> rows, List<DateOnly> prior, DateOnly week)
    {
        var perWeek = rows
            .GroupBy(r => r.WeekStart)
            .ToDictionary(g => g.Key, g => g.Sum(r => r.Events));

        // Zero-fill: a prior complete week with no rows counts as 0 events. That is only true if
        // the caller fetched every complete week up to the target (see Build's contract); a
        // narrower fetch would turn "not fetched" into "silent" and drag the baseline to zero.
        var history = prior.Select(w => perWeek.GetValueOrDefault(w)).ToList();
        var count = perWeek.GetValueOrDefault(week);
        var byType = rows
            .Where(r => r.WeekStart == week)
            .GroupBy(r => r.EventType, StringComparer.Ordinal)
            .OrderBy(g => g.Key, StringComparer.Ordinal)
            .Select(g => new TypeSplit(
                g.Key,
                g.Sum(r => r.Events),
                g.GroupBy(r => r.Outcome ?? UnspecifiedOutcome, StringComparer.Ordinal)
                    .OrderBy(o => o.Key, StringComparer.Ordinal)
                    .ToDictionary(o => o.Key, o => o.Sum(r => r.Events), StringComparer.Ordinal)))
            .ToList();

        return new SeriesPulse(
            location,
            count,
            Math.Min(history.Count, Baseline.Window),
            Significance.Assess(count, Baseline.Lambda(history)),
            byType);
    }

    private static int IndexOf(IReadOnlyList<DateOnly> weeks, DateOnly week)
    {
        for (var i = 0; i < weeks.Count; i++)
        {
            if (weeks[i] == week)
            {
                return i;
            }
        }

        return -1;
    }
}
